    return np.linalg.lstsq(np.column_stack((np.ones(len(raw)), raw)), y.sum(axis=1), rcond=None)[0]

def _fit(x, p, h, dt, t, strain, rate):
    from scipy.optimize import least_squares
    (n, k) = strain.shape
    y = np.r_[strain.ravel(), rate]

    def unpack(u):
        lo = np.exp(u[0])
        return np.array([lo, lo * np.exp(u[1] * (np.log(25.0) - u[0]))])

    def project(u, w):
        (a, b) = _design(unpack(u), x, p, h, dt, t)
        a = np.vstack((a.reshape(-1, 7), b))
        beta = np.linalg.lstsq(a * w[:, None], y * w, rcond=None)[0]
        return (a @ beta - y, beta)

    def solve(u, w):
        return least_squares(lambda v: project(v, w)[0] * w, u, bounds=([np.log(0.05000001), 1e-06], [np.log(24.9999), 0.999999]), diff_step=1e-05, max_nfev=65)
    w = np.ones(len(y))
    starts = [(0.25, 1.8), (0.7, 4.0), (1.4, 11.0), (0.09, 8.0)]
    fits = [solve([np.log(lo), np.log(hi / lo) / np.log(25.0 / lo)], w) for (lo, hi) in starts]
    u = min(fits, key=lambda f: f.cost).x
    for _ in range(12):
        (r, _) = project(u, w)
        rs = (r[:n * k], r[n * k:])
        sig = [max(1e-05, 1.4826 * np.median(np.abs(a - np.median(a)))) for a in rs]
        s = np.repeat(sig, [n * k, n])
        w = 1.0 / np.hypot(s, r / 2.4)
        unew = solve(u, w).x
        if np.max(np.abs(unew - u)) < 2e-07:
            u = unew
            break
        u = unew
    return (unpack(u), project(u, w)[1])
